ltar","territory_id":"frontier","territory_name":"적월 교령","region_name":"적월 제단터","region_type":"ruined_temple","danger_level":9,"min_level":19,"description":"적월교가 붉은 달에 제물을 바치던 바깥 제단 벌판. 돌기둥마다 마른 피가 검게 엉겨 있다.","travel_from":["red_moon_fort","glass_canyon"],"faction_control":"","world_x":95,"world_y":380,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"snow_hollow","territory_id":"north","territory_name":"북령 맹약지","region_name":"설피골","region_type":"ice_valley","danger_level":4,"min_level":5,"description":"북령맹 사냥꾼들이 설피를 신고 드나드는 눈 골짜기. 처음 눈길을 익히는 이들이 많이 찾는다.","travel_from":["paper_bridge","ash_mountain","iron_monastery"],"faction_control":"","world_x":430,"world_y":240,"elevation":3,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"ember_pass","territory_id":"south","territory_name":"남명 망국령","region_name":"불씨 고개","region_type":"mountain_pass","danger_level":4,"min_level":5,"description":"무너진 남녘 나라의 피난민들이 불씨 항아리를 안고 넘던 고개. 고갯마루에는 지금도 화톳불이 꺼지지 않는다.","travel_from":["sealed_garden","ember_village"],"faction_control":"","world_x":625,"world_y":490,"elevation":1,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"lamp_alley","territory_id":"underworld","territory_name":"흑련 지하회랑","region_name":"등잔골 뒷골목","region_type":"underground","danger_level":4,"min_level":5,"description":"도성 아래로 얽힌 좁은 골목. 기름 등잔 불빛 아래에서 흑련회의 좀도둑과 밀수꾼이 오간다.","travel_from":["old_canal","hidden_bazaar","hq_archive"],"faction_control":"","world_x":455,"world_y":455,"elevation":-1,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"star_hill","territory_id":"heavenward","territory_name":"천명 상계","region_name":"별바라기 언덕","region_type":"wilderness","danger_level":4,"min_level":5,"description":"천명원 견습생들이 밤마다 별을 헤아리는 완만한 언덕. 풀벌레 소리 사이로 별자리를 외는 목소리가 들린다.","travel_from":["field_outskirts","jade_pass","water_clock"],"faction_control":"","world_x":570,"world_y":280,"elevation":2,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"water_clock","territory_id":"heavenward","territory_name":"천명 상계","region_name":"물시계 터","region_type":"pavilion","danger_level":6,"min_level":9,"description":"나라의 시각을 알리던 물시계가 무너진 자리. 물이 끊겼는데도 누각의 인형들이 이따금 시보를 울린다.","travel_from":["star_hill","jade_pass","comet_crater"],"faction_control":"","world_x":630,"world_y":195,"elevation":4,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"comet_crater","territory_id":"heavenward","territory_name":"천명 상계","region_name":"혜성 낙하지","region_type":"canyon","danger_level":8,"min_level":13,"description":"오래전 혜성이 떨어져 파인 커다란 구덩이. 녹아 굳은 바위 사이에 별쇠가 박혀 있고 하늘의 짐승들이 내려앉는다.","travel_from":["water_clock","white_tower","cloud_corridor"],"faction_control":"","world_x":640,"world_y":140,"elevation":4,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null},{"region_id":"cloud_corridor","territory_id":"heavenward","territory_name":"천명 상계","region_name":"구름 위 회랑","region_type":"celestial_tower","danger_level":9,"min_level":16,"description":"천명원의 탑과 탑을 구름 위에서 잇는 긴 회랑. 바람이 세서 난간 너머로 떨어진 이가 적지 않다.","travel_from":["comet_crater","white_tower","star_observatory"],"faction_control":"","world_x":740,"world_y":120,"elevation":8,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null}]$J$::jsonb) as x(region_id text, territory_id text, territory_name text, region_name text, region_type text, danger_level int, min_level int, description text, travel_from jsonb, gather_nodes jsonb, faction_control text, is_starting_area boolean, active boolean, world_x int, world_y int, elevation int, terrain_cost numeric, rest_spot_type text, rest_spot_name text, rest_quality int, rest_fee int, rest_risk int, is_safe_zone boolean, shop_id text, shop_name text, has_stable boolean, contested boolean)
