insert into public.world_region_profiles(region_id, biome_key, biome_name, faction_style, signature_clue, signature_event, signature_items, survival_hazard, visual_identity, signature_resources, investigation_reward)
select x.region_id, x.biome_key, x.biome_name, x.faction_style, x.signature_clue, x.signature_event, array(select jsonb_array_elements_text(x.signature_items)), x.survival_hazard, x.visual_identity, array(select jsonb_array_elements_text(x.signature_resources)), x.investigation_reward from jsonb_to_recordset($J$[{"region_id":"old_prison","biome_key":"city","biome_name":"폐허 도성","faction_style":"정통파 옛 옥졸·빙의된 죄수","signature_clue":"옛 의금부 옥사의 죄인 명부: 이름 옆마다 「빙의」라는 붉은 글자와 부적 번호가 적혀 있다.","signature_event":"옛 의금부 옥사 고유 사건: 봉해진 지하 감옥의 빗장이 풀리면 마지막까지 남은 죄수의 이름이 드러난다.","signature_items":["mirror_shard","spirit_dust","ghost_ash"],"survival_hazard":"침식·빙의·사슬","visual_identity":"녹슨 쇠창살, 부적 붙은 감방 문, 국문장의 형틀","signature_resources":["ghost_ash","herb","mirror_shard","raw_iron","seal_paper","sealing_ink","spirit_dust","steel_ingot","talisman_thread","tonic","travel_ration","ward_fragment"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"seal_vault","biome_key":"shrine","biome_name":"사당·서고","faction_style":"정통파 봉인관·새어 나온 압수물","signature_clue":"봉인고의 압수 목록: 목록에 적힌 함의 수보다 실제 함이 하나 더 많다.","signature_event":"봉인고 고유 사건: 목록에 없는 상자를 찾아 다시 봉하면 봉인고 맨 처음의 기록이 열린다.","signature_items":["lantern_oil","travel_ration","tonic"],"survival_hazard":"침식·저주·결계","visual_identity":"금줄 친 서가, 쇠못 박힌 궤짝, 먹물 번진 봉인 목록","signature_resources":["ghost_ash","herb","lantern_oil","mirror_shard","monster_core","rune_plate","seal_paper","sealing_ink","spirit_dust","talisman_thread","tonic","travel_ration","ward_fragment"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"tide_gate","biome_key":"water","biome_name":"물가·바다","faction_style":"수향연맹 수문지기·바다의 요괴","signature_clue":"만조의 갑문 물때 장부: 수문을 연 시각 옆에 갑문으로 들어온 「손님」의 수가 적혀 있다.","signature_event":"만조의 갑문 고유 사건: 만조 때 큰 수문을 제때 닫으면 연맹의 옛 뱃길이 드러난다.","signature_items":["lantern_oil","herb","tonic"],"survival_hazard":"익사·독·밀물","visual_identity":"거대한 수문 날개, 녹슨 도르래, 연맹 깃발 걸린 망루","signature_resources":["drowned_scale","frost_salt","herb","jade_shard","lantern_oil","lumber","ore","raw_iron","reinforced_lumber","resin","river_reed","thunder_ore","tonic","travel_ration","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"crimson_altar","biome_key":"shrine","biome_name":"사당·성역","faction_style":"적월교 순례자·제물의 넋","signature_clue":"적월 제단터의 경문 비석: 붉은 달이 뜨는 밤마다 비석의 글자가 한 줄씩 늘어난다.","signature_event":"적월 제단터 고유 사건: 핏달 제단에 바친 이름을 거두어 오면 교단이 숨긴 의식의 끝이 드러난다.","signature_items":["rune_plate","cinnabar","raw_iron"],"survival_hazard":"침식·출혈·광기","visual_identity":"피 바른 돌기둥, 붉은 깃발, 붉은 모래 깔린 제단","signature_resources":["cinnabar","ember_crystal","ghost_ash","monster_core","ore","raw_iron","rune_plate","seal_paper","spirit_dust","spirit_glass"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"snow_hollow","biome_key":"mountain","biome_name":"산악·설원","faction_style":"북령맹 설피 사냥꾼·눈의 짐승","signature_clue":"설피골의 덫 표식: 사냥꾼마다 다른 매듭으로 덫 자리를 표시해 둔다.","signature_event":"설피골 고유 사건: 눈보라 속 망령의 설피를 찾아 주면 얼어 죽은 사냥꾼의 마지막 길이 드러난다.","signature_items":["beast_hide","herb","travel_ration"],"survival_hazard":"추위·눈보라·매복","visual_identity":"설피 걸린 사냥막, 자작나무 숲, 얼어붙은 못","signature_resources":["beast_hide","charcoal","drowned_scale","frost_salt","herb","medicine_base","moon_moss","resin","river_reed","travel_ration","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"ember_pass","biome_key":"wild","biome_name":"들판·고개","faction_style":"남명회 불씨지기·피난민의 넋","signature_clue":"불씨 고개의 이정비: 남녘으로 가는 길의 이름이 지워지고 「돌아갈 곳」이라고만 적혀 있다.","signature_event":"불씨 고개 고유 사건: 꺼진 봉화에 불씨를 옮기면 남명이 무너지던 밤의 기록이 드러난다.","signature_items":["cinnabar","raw_iron","ore"],"survival_hazard":"화상·독·연기","visual_identity":"꺼지지 않는 화톳불, 불씨 항아리, 그을린 이정표","signature_resources":["charcoal","cinnabar","herb","herbal_extract","medicine_base","ore","raw_iron","resin","tonic","travel_ration","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"lamp_alley","biome_key":"city","biome_name":"지하·도성","faction_style":"흑련회 좀도둑·밀수꾼","signature_clue":"등잔골의 흑련 표식: 문마다 새긴 연꽃 잎의 수로 그 집이 무엇을 숨기는지 안다.","signature_event":"등잔골 뒷골목 고유 사건: 두꺼비 두목의 통행세 장부를 찾으면 뒷골목을 오가는 장물의 길이 드러난다.","signature_items":["shadow_fang","spirit_dust","ghost_ash"],"survival_hazard":"매복·독·어둠","visual_identity":"흔들리는 기름 등잔, 좁은 계단, 연꽃 새긴 문","signature_resources":["fine_paper","ghost_ash","herb","inkstone","seal_paper","sealing_ink","shadow_fang","silk","spirit_dust","tonic","travel_ration"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"star_hill","biome_key":"sky","biome_name":"하늘·언덕","faction_style":"천명원 견습 관측생·별의 넋","signature_clue":"별바라기 언덕의 성도: 견습생들이 그린 별자리 지도마다 없는 별 하나가 그려져 있다.","signature_event":"별바라기 언덕 고유 사건: 잃어버린 성도를 모두 모으면 견습생들이 본 「없는 별」의 자리가 드러난다.","signature_items":["fine_paper","herb","travel_ration"],"survival_hazard":"길 잃음·환영","visual_identity":"별자리 돌판, 견습생 천막, 반딧불 날리는 풀밭","signature_resources":["cloud_cotton","fine_paper","herb","moon_moss","spirit_dust","travel_ration"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"water_clock","biome_key":"sky","biome_name":"누각·유적","faction_style":"천명원 시보관의 후손·멈춘 인형","signature_clue":"물시계 터의 시각 돌판: 마지막으로 새긴 시각에서 바늘이 움직이지 않는다.","signature_event":"물시계 터 고유 사건: 물시계에 다시 물을 대면 나라의 시각이 멈춘 까닭이 드러난다.","signature_items":["reinforced_lumber","lumber","wood"],"survival_hazard":"함정·결계·물","visual_identity":"무너진 누각, 시보 인형, 물 마른 큰 항아리","signature_resources":["inkstone","lumber","moon_moss","ore","raw_iron","reinforced_lumber","river_reed","seal_paper","spirit_glass","spirit_thread","talisman_thread","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"comet_crater","biome_key":"desert","biome_name":"황무지·분화구","faction_style":"천명원 관측관·하늘의 짐승","signature_clue":"혜성 낙하지의 관측 말뚝: 말뚝마다 혜성이 떨어지기 전날의 별 위치가 새겨져 있다.","signature_event":"혜성 낙하지 고유 사건: 혜성 심을 지키는 것을 잠재우면 천명원이 감춘 예언이 드러난다.","signature_items":["sky_feather","herb","tonic"],"survival_hazard":"화상·낙석·하늘빛","visual_identity":"녹아 굳은 바위, 별쇠, 그을린 분화구 둘레","signature_resources":["herb","ore","raw_iron","sky_feather","spirit_dust","spirit_glass","star_sand","thunder_ore","tonic","travel_ration"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"cloud_corridor","biome_key":"sky","biome_name":"하늘·탑","faction_style":"천명원 늙은 천문관·바람의 넋","signature_clue":"구름 위 회랑의 천명 기둥: 기둥마다 회랑을 걷다 떨어진 천문관의 이름이 새겨져 있다.","signature_event":"구름 위 회랑 고유 사건: 회랑 끝 천문 거울을 다시 하늘로 돌리면 마지막 관측 기록이 드러난다.","signature_items":["spirit_bark","moon_moss","cloud_cotton"],"survival_hazard":"추락·번개·바람","visual_identity":"구름 깔린 다리, 끊어진 난간, 별 그림 천장","signature_resources":["cloud_cotton","fine_paper","herb","jade_shard","moon_moss","seal_paper","sky_feather","spirit_bark","spirit_dust","star_sand","talisman_thread"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"}]$J$::jsonb) as x(region_id text, biome_key text, biome_name text, faction_style text, signature_clue text, signature_event text, signature_items jsonb, survival_hazard text, visual_identity text, signature_resources jsonb, investigation_reward text)
on conflict (region_id) do update set biome_name = excluded.biome_name, faction_style = excluded.faction_style, signature_clue = excluded.signature_clue, signature_event = excluded.signature_event, signature_items = excluded.signature_items, survival_hazard = excluded.survival_hazard, visual_identity = excluded.visual_identity, signature_resources = excluded.signature_resources;
insert into public.world_region_lore(region_id, lines)
select x.region_id, x.lines from jsonb_to_recordset($J$[{"region_id":"old_prison","lines":[{"s":null,"t":"옛 의금부 옥사. 야행국 관청이 빙의된 죄인을 가두던 곳입니다. 관청이 문을 닫은 지 오래인데도 감방마다 빗장이 안쪽에서 걸려 있습니다."},{"s":null,"t":"복도 끝에서 쇠사슬 끌리는 소리가 납니다. 순찰 시각을 아직 지키는 누군가가 있습니다."}]},{"region_id":"seal_vault","lines":[{"s":null,"t":"봉인고. 관청이 거둬들인 저주받은 물건들이 함마다 봉해져 있습니다. 함 위의 봉인지는 오래된 것부터 누렇게 들떠 있습니다."},{"s":null,"t":"압수 목록을 세어 보면 함이 하나 더 많습니다. 봉인관들은 그 하나가 무엇인지 아무도 모른다고 합니다."}]},{"region_id":"tide_gate","lines":[{"s":null,"t":"만조의 갑문. 수향연맹이 바닷물을 막으려고 쌓은 갑문입니다. 물때가 바뀔 때마다 도르래가 길게 웁니다."},{"s":null,"t":"만조에는 수문 틈으로 물만 들어오지 않습니다. 수문지기들은 그때 들어온 것들을 「손님」이라 부릅니다."}]},{"region_id":"crimson_altar","lines":[{"s":null,"t":"적월 제단터. 적월교가 붉은 달에 제물을 바치던 벌판입니다. 돌기둥마다 검게 마른 피가 엉겨 있습니다."},{"s":null,"t":"달이 붉어지는 밤이면 아무도 없는 제단에서 북소리가 납니다. 교도들은 지금도 이곳을 성지라 부릅니다."}]},{"region_id":"snow_hollow","lines":[{"s":null,"t":"설피골. 북령맹 사냥꾼들이 설피를 신고 드나드는 눈 골짜기입니다. 눈길을 처음 익히는 이들이 이곳에서 겨울을 배웁니다."},{"s":null,"t":"사냥막 처마에 낡은 설피가 줄줄이 걸려 있습니다. 돌아오지 못한 사냥꾼의 것도 섞여 있습니다."}]},{"region_id":"ember_pass","lines":[{"s":null,"t":"불씨 고개. 남녘 나라가 무너지던 밤, 피난민들이 불씨 항아리를 안고 넘던 고개입니다. 고갯마루의 화톳불은 그날부터 꺼진 적이 없습니다."},{"s":null,"t":"이정비에는 남녘으로 가는 길의 이름이 지워져 있습니다. 대신 누군가 「돌아갈 곳」이라고 새겨 두었습니다."}]},{"region_id":"lamp_alley","lines":[{"s":null,"t":"등잔골 뒷골목. 도성 아래로 얽힌 골목입니다. 기름 등잔 하나가 꺼질 때마다 누군가 그 그늘로 숨어듭니다."},{"s":null,"t":"문마다 작은 연꽃이 새겨져 있습니다. 흑련회 사람들은 잎의 수만 보고도 그 집이 무엇을 숨기는지 압니다."}]},{"region_id":"star_hill","lines":[{"s":null,"t":"별바라기 언덕. 천명원 견습생들이 밤마다 별을 헤아리는 언덕입니다. 풀벌레 소리 사이로 별자리를 외는 목소리가 들립니다."},{"s":null,"t":"견습생들이 그린 성도에는 늘 없는 별이 하나씩 그려져 있습니다. 모두 같은 자리에 그렸다고 합니다."}]},{"region_id":"water_clock","lines":[{"s":null,"t":"물시계 터. 나라의 시각을 알리던 물시계가 무너진 자리입니다. 물이 끊긴 지 오래인데 누각의 인형이 이따금 종을 칩니다."},{"s":null,"t":"시각 돌판의 마지막 눈금에 손때가 짙게 묻어 있습니다. 누군가 그 시각에서 시간을 멈춰 두려 한 것 같습니다."}]},{"region_id":"comet_crater","lines":[{"s":null,"t":"혜성 낙하지. 오래전 혜성이 떨어져 파인 구덩이입니다. 녹아 굳은 바위 틈마다 별쇠가 박혀 하늘빛으로 빛납니다."},{"s":null,"t":"천명원은 혜성이 떨어지기 전날 이 일을 알고 있었다고 합니다. 관측 말뚝에 새긴 날짜가 그것을 말해 줍니다."}]},{"region_id":"cloud_corridor","lines":[{"s":null,"t":"구름 위 회랑. 천명원의 탑과 탑을 구름 위에서 잇는 긴 회랑입니다. 발밑으로 구름이 바다처럼 흐릅니다."},{"s":null,"t":"기둥마다 이름이 새겨져 있습니다. 회랑을 걷다 바람에 떨어진 천문관들의 이름이라고 합니다."}]}]$J$::jsonb) as x(region_id text, lines jsonb)
on conflict (region_id) do update set lines = excluded.lines;
insert into public.world_exploration_nodes(node_id, region_id, parent_node_id, hierarchy_level, node_name, description, min_level, sort_order)
