insert into public.world_region_monsters(monster_id, region_id, monster_name, monster_type, min_level, max_level, hp, attack_power, spawn_weight, description, drops, difficulty_rank, mechanic_key, mechanic_description, role, kind)
select x.monster_id, x.region_id, x.monster_name, x.monster_type, x.min_level, x.max_level, x.hp, x.attack_power, x.spawn_weight, x.description, x.drops, x.difficulty_rank, x.mechanic_key, x.mechanic_description, x.role, x.kind from jsonb_to_recordset($J$[{"monster_id":"r71_prison_1","region_id":"old_prison","monster_name":"칼 쓴 옥귀","monster_type":"원령","min_level":15,"max_level":18,"hp":280,"attack_power":24,"spawn_weight":14,"description":"목에 칼을 쓴 채 죽은 죄수의 혼. 옥사 복도를 밤새 오간다.","drops":{"ghost_ash":1},"difficulty_rank":2,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"common","kind":"ghost"},{"monster_id":"r71_prison_2","region_id":"old_prison","monster_name":"옥사 쥐 떼","monster_type":"무리 요괴","min_level":15,"max_level":18,"hp":280,"attack_power":24,"spawn_weight":14,"description":"죄수들의 밥을 훔쳐 먹다 요기에 물든 쥐 떼. 한꺼번에 발목을 문다.","drops":{"beast_fang":1,"beast_hide":1},"difficulty_rank":2,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"common","kind":"swarm"},{"monster_id":"r71_prison_3","region_id":"old_prison","monster_name":"빙의된 죄수","monster_type":"파봉 요괴","min_level":17,"max_level":21,"hp":2250,"attack_power":112,"spawn_weight":15,"description":"몸에 붙은 부적을 스스로 뜯어낸 죄수. 그 안에서 다른 것이 웃는다.","drops":{"seal_paper":2,"ward_fragment":2,"sealing_ink":1},"difficulty_rank":5,"mechanic_key":"seal_breaker","mechanic_description":"봉인을 약하게 만든다. 부적과 봉인 재료를 챙겨라.","role":"main","kind":"breaker"},{"monster_id":"r71_prison_4","region_id":"old_prison","monster_name":"쇠사슬 옥졸","monster_type":"갑각 요괴","min_level":17,"max_level":21,"hp":2250,"attack_power":112,"spawn_weight":15,"description":"녹슨 사슬을 갑옷처럼 감은 옥졸의 넋. 아직도 순찰을 돈다.","drops":{"raw_iron":3,"ghost_ash":2,"mirror_shard":1},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"r71_prison_5","region_id":"old_prison","monster_name":"의금부 형리귀","monster_type":"지역 우두머리","min_level":15,"max_level":17,"hp":420,"attack_power":34,"spawn_weight":12,"description":"국문장에서 죄인을 다스리던 형리가 요괴가 되었다. 형틀을 통째로 휘두른다.","drops":{"raw_iron":3,"ghost_ash":2,"steel_ingot":1},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"giant"},{"monster_id":"r71_vault_1","region_id":"seal_vault","monster_name":"함에서 기어 나온 손","monster_type":"매복 요괴","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"봉인함 틈으로 뻗어 나온 검은 손. 서가 그늘에서 발목을 잡는다.","drops":{"shadow_fang":1,"seal_paper":1},"difficulty_rank":2,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role":"common","kind":"shadow"},{"monster_id":"r71_vault_2","region_id":"seal_vault","monster_name":"저주 인형 무리","monster_type":"무리 요괴","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"압수된 저주 인형들이 한꺼번에 일어나 바늘을 든다.","drops":{"silk":1},"difficulty_rank":2,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"common","kind":"swarm"},{"monster_id":"r71_vault_3","region_id":"seal_vault","monster_name":"울음 새는 거울","monster_type":"거울 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"봉인 천을 벗고 나온 거울. 비친 사람의 공격을 그대로 되돌린다.","drops":{"mirror_shard":2,"spirit_glass":1,"ward_fragment":2},"difficulty_rank":5,"mechanic_key":"reflect","mechanic_description":"공격의 일부를 되돌린다. 원거리 사격이나 봉인 제압을 써라.","role":"main","kind":"mirror"},{"monster_id":"r71_vault_4","region_id":"seal_vault","monster_name":"금줄 감긴 요도","monster_type":"결계 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"금줄로 꽁꽁 묶인 칼. 금줄이 그대로 결계가 되어 칼을 지킨다.","drops":{"ward_fragment":3,"sealing_ink":2,"steel_ingot":1},"difficulty_rank":5,"mechanic_key":"warded","mechanic_description":"결계를 두른다. 결계를 깨는 한 방을 모아 두어라.","role":"main","kind":"ward"},{"monster_id":"r71_vault_5","region_id":"seal_vault","monster_name":"봉인고의 첫 압수물","monster_type":"지역 우두머리","min_level":19,"max_level":21,"hp":504,"attack_power":40,"spawn_weight":12,"description":"봉인고가 맨 처음 들인 물건. 무엇인지 적힌 기록이 없다. 깨어날 때마다 다른 봉인이 금 간다.","drops":{"ward_fragment":3,"spirit_glass":2,"rune_plate":1},"difficulty_rank":10,"mechanic_key":"seal_breaker","mechanic_description":"봉인을 약하게 만든다. 부적과 봉인 재료를 챙겨라.","role":"guardian","kind":"breaker"},{"monster_id":"r71_tide_1","region_id":"tide_gate","monster_name":"밀물 수귀","monster_type":"수귀","min_level":18,"max_level":21,"hp":322,"attack_power":28,"spawn_weight":14,"description":"만조 때 수문 틈으로 밀려 들어오는 물귀신. 물이 차오를수록 거세진다.","drops":{"drowned_scale":1},"difficulty_rank":2,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"common","kind":"water"},{"monster_id":"r71_tide_2","region_id":"tide_gate","monster_name":"소금 갈매기 떼","monster_type":"비행 요괴","min_level":18,"max_level":21,"hp":322,"attack_power":28,"spawn_weight":14,"description":"갑문 망루에 둥지를 튼 갈매기 요괴. 소금 섞인 깃을 떨구며 내리꽂힌다.","drops":{"sky_feather":1,"frost_salt":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"r71_tide_3","region_id":"tide_gate","monster_name":"도르래 집게","monster_type":"갑각 요괴","min_level":20,"max_level":24,"hp":2700,"attack_power":135,"spawn_weight":15,"description":"도르래 쇠사슬에 붙어 사는 커다란 게 요괴. 집게로 쇠사슬을 끊는다.","drops":{"drowned_scale":3,"raw_iron":2,"thunder_ore":1},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"r71_tide_4","region_id":"tide_gate","monster_name":"해초 독해파리","monster_type":"독충","min_level":20,"max_level":24,"hp":2700,"attack_power":135,"spawn_weight":15,"description":"수문 아래 해초 사이를 떠다니는 독해파리. 촉수에 스치면 몸이 굳는다.","drops":{"venom_gland":2,"drowned_scale":2},"difficulty_rank":5,"mechanic_key":"toxic","mechanic_description":"독을 뿜는다. 해독할 약초와 회복품을 챙겨라.","role":"main","kind":"venom"},{"monster_id":"r71_tide_5","region_id":"tide_gate","monster_name":"만조의 수문귀","monster_type":"지역 우두머리","min_level":18,"max_level":20,"hp":483,"attack_power":39,"spawn_weight":12,"description":"큰 수문 날개에 깃든 바다의 요괴. 만조가 되면 갑문 전체가 그의 몸이 된다.","drops":{"drowned_scale":3,"lantern_oil":2,"jade_shard":1},"difficulty_rank":10,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"guardian","kind":"water"},{"monster_id":"r71_altar_1","region_id":"crimson_altar","monster_name":"핏달 박쥐","monster_type":"비행 요괴","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"붉은 달이 뜨면 제단 위를 맴도는 박쥐 요괴.","drops":{"beast_fang":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"r71_altar_2","region_id":"crimson_altar","monster_name":"제물 원령","monster_type":"원령","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"제단에 바쳐진 이들의 넋. 아직도 제 차례를 기다린다.","drops":{"ghost_ash":1,"cinnabar":1},"difficulty_rank":2,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"common","kind":"ghost"},{"monster_id":"r71_altar_3","region_id":"crimson_altar","monster_name":"적월 광신 요인","monster_type":"결계 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"적월교 경문을 몸에 새긴 광신도의 혼. 경문 한 줄 한 줄이 결계가 된다.","drops":{"cinnabar":3,"ward_fragment":2,"ember_crystal":1},"difficulty_rank":5,"mechanic_key":"warded","mechanic_description":"결계를 두른다. 결계를 깨는 한 방을 모아 두어라.","role":"main","kind":"ward"},{"monster_id":"r71_altar_4","region_id":"crimson_altar","monster_name":"핏빛 모래 그림자","monster_type":"매복 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"붉은 모래 속에 숨었다가 발밑에서 솟구친다.","drops":{"shadow_fang":3,"ghost_ash":2},"difficulty_rank":5,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role