":"별 헤는 능선","description":"별자리 돌판이 흩어진 능선.","depth":2,"danger":5,"min_level":7,"unlock_progress":30},{"ground_id":"star_hill_3","region_id":"star_hill","ground_name":"언덕 꼭대기 별마루","description":"밤새 별을 지켜보는 언덕 꼭대기.","depth":3,"danger":6,"min_level":9,"unlock_progress":70},{"ground_id":"water_clock_1","region_id":"water_clock","ground_name":"마른 수로 둘레","description":"물이 끊긴 수로가 돌아 나가는 바깥.","depth":1,"danger":6,"min_level":9,"unlock_progress":0},{"ground_id":"water_clock_2","region_id":"water_clock","ground_name":"인형 누각 마당","description":"시보 인형들이 서 있는 누각 앞.","depth":2,"danger":7,"min_level":11,"unlock_progress":30},{"ground_id":"water_clock_3","region_id":"water_clock","ground_name":"멈춘 태엽 방","description":"멈춘 장치가 잠든 가장 깊은 곳.","depth":3,"danger":8,"min_level":13,"unlock_progress":70},{"ground_id":"comet_crater_1","region_id":"comet_crater","ground_name":"그을린 분화구 둘레","description":"분화구를 두른 그을린 비탈.","depth":1,"danger":8,"min_level":13,"unlock_progress":0},{"ground_id":"comet_crater_2","region_id":"comet_crater","ground_name":"유리 모래 고랑","description":"혜성 꼬리가 긁고 간 고랑.","depth":2,"danger":9,"min_level":15,"unlock_progress":30},{"ground_id":"comet_crater_3","region_id":"comet_crater","ground_name":"혜성 심 구덩이","description":"혜성의 심이 박힌 분화구 한가운데.","depth":3,"danger":10,"min_level":17,"unlock_progress":70},{"ground_id":"cloud_corridor_1","region_id":"cloud_corridor","ground_name":"구름 다리 어귀","description":"회랑으로 들어서는 첫 구름 다리.","depth":1,"danger":9,"min_level":16,"unlock_progress":0},{"ground_id":"cloud_corridor_2","region_id":"cloud_corridor","ground_name":"바람에 끊긴 회랑","description":"바람에 끊긴 회랑이 다시 이어지는 곳.","depth":2,"danger":10,"min_level":18,"unlock_progress":30},{"ground_id":"cloud_corridor_3","region_id":"cloud_corridor","ground_name":"천문 거울 망대","description":"회랑 끝 거울이 걸린 망대.","depth":3,"danger":10,"min_level":20,"unlock_progress":70}]$J$::jsonb) as x(ground_id text, region_id text, ground_name text, description text, depth int, danger int, min_level int, unlock_progress int)
