-- 기존 캐릭터: 새 지역 들머리 채집터를 찾은 것으로(새 캐릭터는 trg_world_entry_spots)
insert into public.world_gathering_discoveries(owner_id, spot_id)
select c.owner_id, gs.spot_id from public.world_characters c
  cross join public.world_gathering_spots gs join public.world_exploration_nodes n on n.node_id = gs.node_id and n.hierarchy_level = 1 and n.region_id in ('old_prison', 'seal_vault', 'tide_gate', 'crimson_altar', 'snow_hollow', 'ember_pass', 'lamp_alley', 'star_hill', 'water_clock', 'comet_crater', 'cloud_corridor')
on conflict do nothing;
insert into public.world_quest_npcs(npc_key, npc_name, bio)
select x.npc_key, x.npc_name, x.bio from jsonb_to_recordset($J$[{"npc_key":"q:r71_machun","npc_name":"늙은 옥졸 마춘","bio":"의금부가 문을 닫던 날까지 옥사를 지킨 정통파 옥졸. 지금도 열쇠 꾸러미를 허리에 차고 다닌다."},{"npc_key":"q:r71_hayunjae","npc_name":"봉인관 하윤재","bio":"봉인고를 홀로 맡은 정통파 봉인관. 압수 목록을 외울 만큼 읽었지만 함 하나의 정체만은 모른다."},{"npc_key":"q:r71_jomaksim","npc_name":"수문지기 조막심","bio":"만조의 갑문을 삼대째 지키는 수향연맹 수문지기. 물때를 손가락 마디로 센다."},{"npc_key":"q:r71_somae","npc_name":"소매","bio":"적월교를 떠난 옛 교도. 붉은 소매로 손목의 인두 자국을 가리고 다닌다."},{"npc_key":"q:r71_gombae","npc_name":"곰배 영감","bio":"북령맹 설피 장인. 설피골 사냥꾼들의 설피는 거의 다 그의 손을 거쳤다."},{"npc_key":"q:r71_arang","npc_name":"불씨지기 아랑","bio":"고갯마루 화톳불을 지키는 남명회 아가씨. 남녘을 본 적은 없지만 남녘 노래를 다 안다."},{"npc_key":"q:r71_soetdae","npc_name":"등잔 장수 쇳대","bio":"등잔골 계단 아래 좌판을 펴는 흑련회 끄트머리 장사꾼. 입은 험하지만 셈은 정직하다."},{"npc_key":"q:r71_byeori","npc_name":"견습 관측생 별이","bio":"천명원에 들어온 지 한 해 된 견습생. 성도를 잃어버려 스승에게 혼날 날만 기다리고 있다."},{"npc_key":"q:r71_nuri","npc_name":"누리","bio":"물시계를 돌보던 시보관 집안의 마지막 후손. 집안에 내려오는 태엽 열쇠를 목에 걸고 다닌다."},{"npc_key":"q:r71_seoharam","npc_name":"천명원 관측관 서하람","bio":"혜성 낙하지를 지키는 천명원 관측관. 별쇠 이야기만 나오면 밤을 새운다."},{"npc_key":"q:r71_undam","npc_name":"늙은 천문관 운담","bio":"구름 위 회랑에 홀로 남은 천명원 천문관. 눈이 흐려져 이제는 별 대신 바람 소리로 하늘을 읽는다."}]$J$::jsonb) as x(npc_key text, npc_name text, bio text)
on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, sort, epilogue, active)
select x.quest_id, 'side', x.cat, x.title, x.summary, x.region_id, x.min_level, array(select jsonb_array_elements_text(x.after)), x.sort, x.epilogue, true from jsonb_to_recordset($J$[{"quest_id":"rq_old_prison","cat":"전투·옥사","title":"빗장 풀린 옥사","summary":"문 닫은 의금부 옥사에 아직도 순찰을 도는 늙은 옥졸이 있다. 감방 빗장이 하나씩 안쪽에서 풀리고 있다고 한다.","region_id":"old_prison","min_level":15,"after":[],"sort":900,"epilogue":[]},{"quest_id":"rq_seal_vault","cat":"조사·봉인고","title":"목록에 없는 상자","summary":"봉인고의 압수 목록보다 함이 하나 더 많다. 홀로 남은 봉인관 하윤재는 그 하나가 깨어나고 있다고 믿는다.","region_id":"seal_vault","min_level":19,"after":[],"sort":901,"epilogue":[]},{"quest_id":"rq_tide_gate","cat":"채집·갑문","title":"만조를 기다리는 사람","summary":"만조의 갑문을 삼대째 지키는 수문지기 조막심은 녹슨 도르래를 고칠 재료를 구하고 있다. 다음 큰 만조가 머지않았다.","region_id":"tide_gate","min_level":18,"after":[],"sort":902,"epilogue":[]},{"quest_id":"rq_crimson_altar","cat":"전투·제단","title":"붉은 달 아래 순례자","summary":"적월교를 떠난 옛 교도 소매가 제단터를 다시 찾았다. 제단에 바쳐진 동생의 넋이 아직 제 차례를 기다리고 있다고 한다.","region_id":"crimson_altar","min_level":19,"after":[],"sort":903,"epilogue":[]},{"quest_id":"rq_snow_hollow","cat":"채집·설피골","title":"설피 장인의 겨울 채비","summary":"설피골의 설피 장인 곰배 영감은 겨울을 앞두고 새 설피를 엮을 재료가 모자라다. 눈길을 처음 익히는 이에게 맡길 만한 일이다.","region_id":"snow_hollow","min_level":5,"after":[],"sort":904,"epilogue":[]},{"quest_id":"rq_ember_pass","cat":"조사·고개","title":"꺼지지 않는 불씨","summary":"불씨 고개의 화톳불을 지키는 아랑은 남명이 무너지던 밤 꺼진 봉화에 다시 불을 옮기고 싶어 한다.","region_id":"ember_pass","min_level":5,"after":[],"sort":905,"epilogue":[]},{"quest_id":"rq_lamp_alley","cat":"전투·뒷골목","title":"등잔골 통행세","summary":"등잔골 뒷골목의 등잔 장수 쇳대는 하수구 두꺼비 두목이 매기는 통행세에 장사를 접을 판이다.","region_id":"lamp_alley","min_level":5,"after":[],"sort":906,"epilogue":[]},{"quest_id":"rq_star_hill","cat":"조사·별자리","title":"견습생의 잃어버린 성도","summary":"천명원 견습생 별이가 별바라기 언덕에서 성도를 잃어버렸다. 부엉이 요괴가 물어 갔다고 한다.","region_id":"star_hill","min_level":5,"after":[],"sort":907,"epilogue":[]},{"quest_id":"rq_water_clock","cat":"제작·물시계","title":"멈춘 시각을 다시","summary":"물시계를 돌보던 시보관 집안의 마지막 후손 누리는 무너진 물시계에 다시 물을 대려 한다.","region_id":"water_clock","min_level":9,"after":[],"sort":908,"epilogue":[]},{"quest_id":"rq_comet_crater","cat":"채집·별쇠","title":"하늘에서 떨어진 쇠","summary":"혜성 낙하지를 지키는 천명원 관측관 서하람은 혜성이 떨어지기 전날의 기록과 별쇠가 무언가를 말해 준다고 믿는다.","region_id":"comet_crater","min_level":13,"after":[],"sort":909,"epilogue":[]},{"quest_id":"rq_cloud_corridor","cat":"전투·회랑","title":"구름 위의 마지막 관측","summary":"구름 위 회랑에 홀로 남은 늙은 천문관 운담은 회랑 끝 천문 거울을 다시 하늘로 돌려 마지막 관측을 하고 싶어 한다.","region_id":"cloud_corridor","min_level":16,"after":[],"sort":910,"epilogue":[]}]$J$::jsonb) as x(quest_id text, kind text, cat text, title text, summary text, region_id text, min_level int, after jsonb, sort int, epilogue jsonb, active boolean)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, epilogue = excluded.epilogue, active = excluded.active;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward)
select x.quest_id, x.step, x.title, x.goal, x.need, x.lines, x.reward from jsonb_to_recordset($J$[{"quest_id":"rq_old_prison","step":1,"title":"열쇠 꾸러미","goal":"옛 의금부 옥사에서 늙은 옥졸 마춘을 만난다","need":{"at":["old_prison"]},"lines":[{"s":null,"t":"무너진 옥문 앞에서 쇠붙이 부딪치는 소리가 난다. 허리에 열쇠 꾸러미를 찬 노인이 문틀을 더듬고 있다."},{"s":"q:r71_machun","t":"거기 누구요. 면회 시각은 진작 지났소."},{"s":"me","t":"야행국에서 왔습니다. 옥사에서 소리가 난다고 들었습니다."},{"s":"q:r71_machun","t":"…관청 사람이구먼. 의금부가 문을 닫은 지 몇 해인데, 이제야 오는구려."},{"s":null,"t":"노인이 열쇠 하나를 들어 보인다. 이가 다 닳아 어느 자물쇠에도 맞지 않을 것 같다."},{"s":"q:r71_machun","t":"감방 빗장이 안쪽에서 풀리고 있소. 나는 바깥에서 잠갔는데 말이오. 안에 아직 누가 있다는 소리지."},{"s":"q:r71_machun","t":"나 혼자서는 복도 끝까지 못 가오. 좀 따라와 주시겠소?"}],"reward":{}},{"quest_id":"rq_old_prison","step":2,"title":"칼 쓴 죄인들","goal":"칼 쓴 옥귀를 4번 쓰러뜨린다","need":{"at":["old_prison"],"tasks":[{"t":"win","m":["r71_prison_1"],"n":4}]},"lines":[{"s":null,"t":"쇠창살 복도에 목에 칼을 쓴 그림자들이 줄지어 서 있다. 칼 끝이 바닥을 긁는 소리가 길게 이어진다."},{"s":null,"t":"마지막 그림자가 흩어지자 칼이 바닥에 떨어져 두 동강 난다. 나무 안쪽에 이름 하나가 새겨져 있다."},{"s":"q:r71_machun","t":"…그 칼은 내가 씌운 것이오. 죄목은 「빙의」 하나였지."},{"s":"q:r71_machun","t":"요괴가 붙은 사람은 죄인이 아니라고 말한 동료도 있었소. 그 사람도 결국 이 복도로 들어왔지만."},{"s":"me","t":"그분은 어떻게 되었습니까?"},{"s":"q:r71_machun","t":"모르오. 그날 밤 내가 받은 명은 빗장을 걸라는 것뿐이었으니까."},{"s":null,"t":"노인의 손이 열쇠 꾸러미를 꽉 쥔다. 열쇠들이 서로 부딪쳐 작게 운다."}],"reward":{"xp":560}},{"quest_id":"rq_old_prison","step":3,"title":"뜯긴 부적","goal":"빙의된 죄수를 2번 쓰러뜨리고 마춘에게 봉인 종이 3장을 건넨다","need":{"at":["old_prison"],"tasks":[{"t":"win","m":["r71_prison_3"],"n":2}],"give":{"seal_paper":3}},"lines":[{"s":null,"t":"감방 벽마다 부적이 덕지덕지 붙어 있다. 그 가운데 몇 장은 안쪽에서 손톱으로 뜯어낸 자국이 있다."},{"s":"q:r71_machun","t":"빙의된 이들이 스스로 부적을 뜯는 것이오. 안에 든 것이 나오고 싶어 하니까."},{"s":null,"t":"마춘이 봉인 종이를 받아 침을 묻혀 한 장씩 빗장에 붙인다. 손이 떨리지만 붙이는 자리는 정확하다."},{"s":"q:r71_machun","t":"옛날엔 하루에 백 장도 붙였소. 손이 기억하는구먼."},{"s":"me","t":"이렇게까지 지키시는 까닭이 있습니까?"},{"s":"q:r71_machun","t":"내가 잠근 문이니 내가 지켜야지. 열지도 못하고 버리지도 못하는 게 옥졸이오."},{"s":null,"t":"지하로 내려가는 계단 아래에서 형틀이 끌리는 소리가 난다."}],"reward":{"xp":560}},{"quest_id":"rq_old_prison","step":4,"title":"국문장의 형리","goal":"의금부 형리귀를 쓰러뜨린다","need":{"at":["old_prison"],"tasks":[{"t":"win","m":["r71_prison_5"],"n":1}]},"lines":[{"s":null,"t":"형리귀가 형틀째 무너진다. 국문장 마당에 오래 고여 있던 신음이 한꺼번에 빠져나가듯 조용해진다."},{"s":null,"t":"형틀 아래에서 녹슨 열쇠 하나가 나온다. 마춘의 꾸러미에 없는 열쇠다."},{"s":"q:r71_machun","t":"…이건 지하 감옥 열쇠요. 형리 나리가 늘 품에 넣고 다니던."},{"s":"q:r71_machun","t":"그 동료가 들어간 곳이 저 아래였구먼. 나는 끝내 문을 열어 보지 못했소."},{"s":null,"t":"마춘이 열쇠를 한참 들여다보다가 꾸러미 맨 끝에 끼운다."},{"s":"q:r71_machun","t":"오늘은 열지 않겠소. 대신 내일도 순찰을 돌 것이오. 이 열쇠를 차고."},{"s":"q:r71_machun","t":"고맙소, 관청 사람. 이 옥사에 처음으로 바깥 발소리가 들렸구려."}],"reward":{"xp":560,"gil":65,"items":{"ward_talisman":2,"tonic":3,"sealing_ink":2}}},{"quest_id":"rq_seal_vault","step":1,"title":"하나 더 많은 함","goal":"봉인고에서 봉인관 하윤재를 만난다","need":{"at":["seal_vault"]},"lines":[{"s":null,"t":"봉인고 정문을 밀자 먹 냄새와 쇠 냄새가 함께 밀려 나온다. 서가 사이로 촛불 하나가 흔들린다."},{"s":"q:r71_hayunjae","t":"발소리를 낮춰 주시오. 여기 있는 것들은 소리에 잘 깹니다."},{"s":null,"t":"젊은 봉인관이 두꺼운 목록을 품에 안고 다가온다. 눈 밑이 검게 꺼져 있다."},{"s":"q:r71_hayunjae","t":"나는 하윤재, 이 봉인고를 맡고 있소. 혼자서."},{"s":"q:r71_hayunjae","t":"목록에는 함이 천이백 개요. 그런데 매일 밤 세어 보면 천이백하나가 나오오. 날마다 같은 수요."},{"s":"me","t":"어느 함이 더 있는지 모르십니까?"},{"s":"q:r71_hayunjae","t":"모르오. 그 함은 늘 다른 자리에 있소. 그래서 찾아 달라는 것이오."}],"reward":{}},{"quest_id":"rq_seal_vault","step":2,"title":"바늘 든 인형들","goal":"저주 인형 무리를 3번 쓰러뜨리고 봉인고에서 결계 파편을 3개 거둔다","need":{"at":["seal_vault"],"tasks":[{"t":"win","m":["r71_vault_2"],"n":3},{"t":"gather","items":["ward_fragment"],"r":["seal_vault"],"n":3}]},"lines":[{"s":null,"t":"저주 인형 창고의 인형들이 한꺼번에 고개를 돌린다. 바늘 끝이 모두 한 방향을 가리킨다."},{"s":null,"t":"인형들이 쓰러진 뒤에도 바늘은 같은 쪽을 향한 채 떨고 있다. 서가 맨 안쪽이다."},{"s":"q:r71_hayunjae","t":"…인형들이 길을 가리키고 있소. 저주는 제 주인을 알아보니까."},{"s":null,"t":"결계 파편을 모아 서가 앞에 늘어놓자 파편들이 저절로 한 줄로 이어진다. 끊긴 봉인의 자리다."},{"s":"q:r71_hayunjae","t":"이 봉인은 내가 붙인 것이 아니오. 먹 색이 다르오. 아주 오래된 먹이오."},{"s":"q:r71_hayunjae","t":"봉인고가 처음 문을 열 때 쓰던 먹이오. 그때의 목록은 남아 있지 않소."}],"reward":{"xp":831}},{"quest_id":"rq_seal_vault","step":3,"title":"되비치는 거울","goal":"울음 새는 거울을 2번 쓰러뜨린다","need":{"at":["seal_vault"],"tasks":[{"t":"win","m":["r71_vault_3"],"n":2}]},"lines":[{"s":null,"t":"거울 창고에서 누군가 우는 소리가 난다. 거울마다 우는 얼굴이 비치지만 거울 앞에는 아무도 없다."},{"s":null,"t":"마지막 거울이 깨지며 조각 하나에 낡은 장부가 비친다. 표지에 「첫 압수」라고 적혀 있다."},{"s":"q:r71_hayunjae","t":"첫 압수…. 봉인고가 맨 처음 거둔 물건이란 말이오?"},{"s":"me","t":"목록에 없는 함이 그것일 수도 있겠군요."},{"s":"q:r71_hayunjae","t":"처음 것은 목록에 적지 않았던 모양이오. 적는 것만으로도 봉인이 풀릴까 두려웠는지도 모르지."},{"s":null,"t":"하윤재가 붓을 꺼내 목록 맨 앞 빈자리를 쓰다듬는다. 붓끝이 떨린다."}],"reward":{"xp":831}},{"quest_id":"rq_seal_vault","step":4,"title":"첫 압수물","goal":"봉인고의 첫 압수물을 쓰러뜨린다","need":{"at":["seal_vault"],"tasks":[{"t":"win","m":["r71_vault_5"],"n":1}]},"lines":[{"s":null,"t":"바닥 갈라진 깊은 창고에서 함 하나가 저절로 열린다. 안은 비어 있다. 그 빈 것이 일어선다."},{"s":null,"t":"싸움이 끝나자 빈 함 안쪽 바닥에 글씨가 드러난다. 「이것은 우리가 처음으로 두려워한 것이다」."},{"s":"q:r71_hayunjae","t":"…물건이 아니었구려. 두려움 자체를 봉해 둔 것이었소."},{"s":"q:r71_hayunjae","t":"그래서 이름을 적을 수 없었던 것이오. 적으면 모두가 알게 되니까."},{"s":null,"t":"하윤재가 목록 맨 앞 빈자리에 천천히 적는다. 「첫 압수 — 두려움. 다시 봉함.」"},{"s":"q:r71_hayunjae","t":"이제 내일 밤에는 천이백 개가 맞을 것이오. 아니, 천이백하나라고 적었으니 그게 맞는 수요."},{"s":"q:r71_hayunjae","t":"고맙소. 혼자 세는 밤이 조금 덜 길어지겠소."}],"reward":{"xp":831,"gil":81,"items":{"ward_talisman":3,"sealing_ink":2,"spirit_glass":1}}},{"quest_id":"rq_tide_gate","step":1,"title":"물때를 세는 손","goal":"만조의 갑문에서 수문지기 조막심을 만난다","need":{"at":["tide_gate"]},"lines":[{"s":null,"t":"갑문 앞 선착장에 짠 바람이 분다. 망루 꼭대기에서 연맹 깃발이 찢어질 듯 펄럭인다."},{"s":null,"t":"망루 아래에서 늙은 여인이 손가락 마디를 하나씩 접으며 무언가를 센다."},{"s":"q:r71_jomaksim","t":"…열하나, 열둘. 사흘 뒤가 큰 만조구먼."},{"s":"q:r71_jomaksim","t":"아, 손님이시우. 수문지기 조막심이오. 할머니 때부터 이 갑문을 지켰지."},{"s":"q:r71_jomaksim","t":"큰 만조에는 도르래를 다 써서 수문을 닫아야 하우. 헌데 도르래 축이 썩어 버렸어."},{"s":"me","t":"무엇이 필요하십니까?"},{"s":"q:r71_jomaksim","t":"물에 젖어도 안 썩는 나무랑, 축에 바를 비늘 기름이지. 갑문에서 다 구할 수 있수."}],"reward":{}},{"quest_id":"rq_tide_gate","step":2,"title":"물속의 재료","goal":"만조의 갑문에서 물고기를 2번 낚고 물에 빠진 비늘을 3개 거둔다","need":{"at":["tide_gate"],"tasks":[{"t":"fish","r":["tide_gate"],"n":2},{"t":"gather","items":["drowned_scale"],"r":["tide_gate"],"n":3}]},"lines":[{"s":null,"t":"수문 틈으로 밀려든 물이 소용돌이친다. 찌가 물살에 휩쓸려 금세 깊이 잠긴다."},{"s":"q:r71_jomaksim","t":"그렇지, 갑문 물고기는 바다랑 강을 다 아는 놈들이우. 기름이 실하지."},{"s":null,"t":"조막심이 물고기 배를 갈라 기름을 짜고, 물에 빠진 비늘을 갈아 섞는다. 비린내가 진동한다."},{"s":"q:r71_jomaksim","t":"우리 할머니가 이걸 축에 바르면서 그러셨수. 바다 것으로 바다를 막는 거라고."},{"s":"me","t":"수향연맹 사람들은 모두 이렇게 배웁니까?"},{"s":"q:r71_jomaksim","t":"연맹은 배를 띄우는 법을 가르치지. 물을 막는 법은 우리 집안만 알우."}],"reward":{"xp":758}},{"quest_id":"rq_tide_gate","step":3,"title":"썩지 않는 나무","goal":"조막심에게 목재 2개를 건네고 도르래 집게를 3번 쓰러뜨린다","need":{"at":["tide_gate"],"tasks":[{"t":"win","m":["r71_tide_3"],"n":3}],"give":{"lumber":2}},"lines":[{"s":null,"t":"도르래 탑에 올라서자 쇠사슬마다 커다란 게가 들러붙어 집게질을 하고 있다."},{"s":null,"t":"마지막 집게가 떨어져 나가자 사슬이 처음으로 매끄럽게 감긴다. 탑 전체가 길게 숨을 내쉬는 소리가 난다."},{"s":"q:r71_jomaksim","t":"저놈들이 사슬을 끊어 먹어서 수문이 반만 닫혔던 거우."},{"s":null,"t":"조막심이 목재를 다듬어 썩은 축 옆에 덧댄다. 망치 소리가 물소리에 섞여 박자를 맞춘다."},{"s":"q:r71_jomaksim","t":"다 됐수. 이제 큰 만조가 와도 끝까지 닫을 수 있겠어."},{"s":"q:r71_jomaksim","t":"…오는 것이 물만은 아닐 테지만."}],"reward":{"xp":758}},{"quest_id":"rq_tide_gate","step":4,"title":"큰 만조","goal":"만조의 수문귀를 쓰러뜨린다","need":{"at":["tide_gate"],"tasks":[{"t":"win","m":["r71_tide_5"],"n":1}]},"lines":[{"s":null,"t":"큰 만조. 바다가 갑문 높이까지 부풀어 오른다. 수문 날개 위에 물로 된 거대한 몸이 일어선다."},{"s":null,"t":"수문귀가 무너지자 조막심이 도르래를 힘껏 돌린다. 수문 날개가 바다를 밀어내며 닫힌다."},{"s":"q:r71_jomaksim","t":"닫혔수! 할머니, 닫혔어요!"},{"s":null,"t":"물이 빠진 수문 아래, 뻘 속에서 오래된 석등 하나가 드러난다. 연맹의 옛 뱃길 표식이다."},{"s":"q:r71_jomaksim","t":"이게 여기 있었구먼. 할머니가 늘 말하던 옛 뱃길 등불이우."},{"s":"q:r71_jomaksim","t":"손님 덕에 이번 물때는 넘겼수. 다음 물때도 넘기겠지. 우리 집안은 그렇게 살아왔으니까."}],"reward":{"xp":758,"gil":77,"items":{"tonic":3,"lantern_oil":2,"travel_ration":2}}},{"quest_id":"rq_crimson_altar","step":1,"title":"붉은 소매","goal":"적월 제단터에서 옛 교도 소매를 만난다","need":{"at":["crimson_altar"]},"lines":[{"s":null,"t":"핏빛 돌길 끝에 붉은 깃발이 늘어서 있다. 바람이 없는데 깃발이 한 방향으로만 나부낀다."},{"s":null,"t":"순례자 천막 자리에 여자 하나가 무릎을 꿇고 있다. 붉은 소매가 손목을 덮고 있다."},{"s":"q:r71_somae","t":"…교도는 아니군요. 다행이에요. 교도였다면 나를 끌고 갔을 테니."},{"s":"q:r71_